#!/usr/bin/env node
/* Checks for the 自他動詞 test bank (generated by tools/gen_jita.cjs). */
const fs = require('fs');
const SIMPLIFIED = new Set([...'间问际实验证议务运过见产车单压长关头发汉语纪给结经济应该两动员术业样齐认产权让']);
const files = [['tota', 'Q1'], ['toji', 'Q2'], ['ukemi', 'Q3'], ['shieki', 'Q4'], ['teiru', 'Q5'], ['hantei', 'Q6']];
const html = fs.readFileSync('src/jita/map.html', 'utf8');
const pairs = html.match(/const RAW = `([\s\S]*?)`;/)[1].trim().split('\n').length;
let bad = 0; const hits = [];
const flag = (where, s) => { if (typeof s !== 'string') return; const b = [...s].filter(c => SIMPLIFIED.has(c)); if (b.length) hits.push(`  ${where}  ${b.join('')}  →  ${s.slice(0, 50)}`); };
for (const [name, v] of files) {
  const arr = eval(fs.readFileSync(`src/jita-quiz/data/${name}.js`, 'utf8').replace(new RegExp(`^[\\s\\S]*?const ${v} =`), ''));
  const g = {}; arr.forEach(q => g[q[0]] = (g[q[0]] || 0) + 1);
  const shape = arr.filter(q => q.length !== 7 || q[2].length !== 4 || typeof q[1] !== 'string' || typeof q[3] !== 'string').length;
  const dup = arr.filter(q => new Set(q[2]).size !== 4).length;
  const sorted = arr.every((q, i) => i === 0 || q[0] >= arr[i - 1][0]);
  arr.forEach((q, i) => { flag(`${name}#${i + 1} stem`, q[1]); q[2].forEach(o => flag(`${name}#${i + 1} option`, o)); });
  console.log(`  jita/${name}: ${arr.length} items, per group ${[1, 2, 3, 4, 5, 6, 7].map(l => g[l] || 0).join('/')}, bad shape ${shape}, dup options ${dup}, grouped ${sorted}`);
  if (arr.length !== pairs || shape || dup || !sorted) bad = 1;
}
console.log(`  jita: ${pairs} pairs in the map`);
if (hits.length) { console.log('MIXED SCRIPT in Japanese fields:'); console.log(hits.join('\n')); bad = 1; } else console.log('  jita mixed-script scan: clean');
process.exit(bad);
